// AssetClient is the client API for Asset service.
//
// For semantics around ctx use and closing/ending streaming RPCs, please refer to https://pkg.go.dev/google.golang.org/grpc/?tab=doc#ClientConn.NewStream.
//
// 内部资产服务
type AssetClient interface {
	// 内部查询指定钱包余额，供风险引擎读取统一资产账本。
	GetAssetBalance(ctx context.Context, in *GetUserAssetDetailReq, opts ...grpc.CallOption) (*GetUserAssetDetailResp, error)
	// 按幂等业务键查询资产流水，用于业务服务对账。
	GetAssetFlowByBizNo(ctx context.Context, in *GetAssetFlowByBizNoReq, opts ...grpc.CallOption) (*GetAssetFlowByBizNoResp, error)
	// 增加可用余额
	AddAvailable(ctx context.Context, in *AddAvailableReq, opts ...grpc.CallOption) (*ChangeAssetResp, error)
	// 扣减可用余额
	SubAvailable(ctx context.Context, in *SubAvailableReq, opts ...grpc.CallOption) (*ChangeAssetResp, error)
	// 冻结余额
	FreezeAsset(ctx context.Context, in *FreezeAssetReq, opts ...grpc.CallOption) (*FreezeAssetResp, error)
	// 解冻余额
	UnfreezeAsset(ctx context.Context, in *UnfreezeAssetReq, opts ...grpc.CallOption) (*ChangeAssetResp, error)
	// 按业务单号解冻余额
	UnfreezeAssetByBizNo(ctx context.Context, in *UnfreezeAssetByBizNoReq, opts ...grpc.CallOption) (*ChangeAssetResp, error)
	// 扣减冻结余额
	DeductFrozenAsset(ctx context.Context, in *DeductFrozenAssetReq, opts ...grpc.CallOption) (*ChangeAssetResp, error)
	// 按业务单号扣减冻结余额
	DeductFrozenAssetByBizNo(ctx context.Context, in *DeductFrozenAssetByBizNoReq, opts ...grpc.CallOption) (*ChangeAssetResp, error)
	// 锁仓
	LockAsset(ctx context.Context, in *LockAssetReq, opts ...grpc.CallOption) (*LockAssetResp, error)
	// 解锁
	UnlockAsset(ctx context.Context, in *UnlockAssetReq, opts ...grpc.CallOption) (*ChangeAssetResp, error)
	// 按业务单号解锁
	UnlockAssetByBizNo(ctx context.Context, in *UnlockAssetByBizNoReq, opts ...grpc.CallOption) (*ChangeAssetResp, error)
	// 扣减锁仓余额
	DeductLockedAsset(ctx context.Context, in *DeductLockedAssetReq, opts ...grpc.CallOption) (*ChangeAssetResp, error)
	// 按业务单号扣减锁仓余额
	DeductLockedAssetByBizNo(ctx context.Context, in *DeductLockedAssetByBizNoReq, opts ...grpc.CallOption) (*ChangeAssetResp, error)
	// 钱包划转
	TransferAsset(ctx context.Context, in *TransferAssetReq, opts ...grpc.CallOption) (*TransferAssetResp, error)
	// 从租户保险基金账户原子扣减，余额不足时允许部分赔付。
	CoverInsuranceDeficit(ctx context.Context, in *CoverInsuranceDeficitReq, opts ...grpc.CallOption) (*CoverInsuranceDeficitResp, error)
	ReverseInsuranceCover(ctx context.Context, in *ReverseInsuranceCoverReq, opts ...grpc.CallOption) (*ChangeAssetResp, error)
	CoverPlatformBackstopDeficit(ctx context.Context, in *CoverPlatformBackstopDeficitReq, opts ...grpc.CallOption) (*CoverPlatformBackstopDeficitResp, error)
	// 将业务手续费原子、幂等计入租户平台手续费收入账户。
	CreditPlatformRevenue(ctx context.Context, in *CreditPlatformRevenueReq, opts ...grpc.CallOption) (*CreditPlatformRevenueResp, error)
	// 从租户平台资金账户原子、幂等支付到用户钱包。
	PayPlatformExpense(ctx context.Context, in *PayPlatformExpenseReq, opts ...grpc.CallOption) (*PlatformTransferResp, error)
	// 从用户锁仓本金原子扣减并计入租户平台收入账户。
	CollectLockedRevenue(ctx context.Context, in *CollectLockedRevenueReq, opts ...grpc.CallOption) (*PlatformTransferResp, error)
}

