// AssetServer is the server API for Asset service.
// All implementations must embed UnimplementedAssetServer
// for forward compatibility.
//
// 内部资产服务
type AssetServer interface {
	// 内部查询指定钱包余额，供风险引擎读取统一资产账本。
	GetAssetBalance(context.Context, *GetUserAssetDetailReq) (*GetUserAssetDetailResp, error)
	// 按幂等业务键查询资产流水，用于业务服务对账。
	GetAssetFlowByBizNo(context.Context, *GetAssetFlowByBizNoReq) (*GetAssetFlowByBizNoResp, error)
	// 增加可用余额
	AddAvailable(context.Context, *AddAvailableReq) (*ChangeAssetResp, error)
	// 扣减可用余额
	SubAvailable(context.Context, *SubAvailableReq) (*ChangeAssetResp, error)
	// 冻结余额
	FreezeAsset(context.Context, *FreezeAssetReq) (*FreezeAssetResp, error)
	// 解冻余额
	UnfreezeAsset(context.Context, *UnfreezeAssetReq) (*ChangeAssetResp, error)
	// 按业务单号解冻余额
	UnfreezeAssetByBizNo(context.Context, *UnfreezeAssetByBizNoReq) (*ChangeAssetResp, error)
	// 扣减冻结余额
	DeductFrozenAsset(context.Context, *DeductFrozenAssetReq) (*ChangeAssetResp, error)
	// 按业务单号扣减冻结余额
	DeductFrozenAssetByBizNo(context.Context, *DeductFrozenAssetByBizNoReq) (*ChangeAssetResp, error)
	// 锁仓
	LockAsset(context.Context, *LockAssetReq) (*LockAssetResp, error)
	// 解锁
	UnlockAsset(context.Context, *UnlockAssetReq) (*ChangeAssetResp, error)
	// 按业务单号解锁
	UnlockAssetByBizNo(context.Context, *UnlockAssetByBizNoReq) (*ChangeAssetResp, error)
	// 扣减锁仓余额
	DeductLockedAsset(context.Context, *DeductLockedAssetReq) (*ChangeAssetResp, error)
	// 按业务单号扣减锁仓余额
	DeductLockedAssetByBizNo(context.Context, *DeductLockedAssetByBizNoReq) (*ChangeAssetResp, error)
	// 钱包划转
	TransferAsset(context.Context, *TransferAssetReq) (*TransferAssetResp, error)
	// 从租户保险基金账户原子扣减，余额不足时允许部分赔付。
	CoverInsuranceDeficit(context.Context, *CoverInsuranceDeficitReq) (*CoverInsuranceDeficitResp, error)
	ReverseInsuranceCover(context.Context, *ReverseInsuranceCoverReq) (*ChangeAssetResp, error)
	CoverPlatformBackstopDeficit(context.Context, *CoverPlatformBackstopDeficitReq) (*CoverPlatformBackstopDeficitResp, error)
	// 将业务手续费原子、幂等计入租户平台手续费收入账户。
	CreditPlatformRevenue(context.Context, *CreditPlatformRevenueReq) (*CreditPlatformRevenueResp, error)
	// 从租户平台资金账户原子、幂等支付到用户钱包。
	PayPlatformExpense(context.Context, *PayPlatformExpenseReq) (*PlatformTransferResp, error)
	// 从用户锁仓本金原子扣减并计入租户平台收入账户。
	CollectLockedRevenue(context.Context, *CollectLockedRevenueReq) (*PlatformTransferResp, error)
	mustEmbedUnimplementedAssetServer()
}

